import React, { useState, useEffect } from 'react';
import { Search, ChevronLeft, ChevronRight, Heart } from 'lucide-react';

const ProductCard = ({ product, onToggleSave, isSaved }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const images = product.images || [];
  const hasMultipleImages = images.length > 1;

  // Condition badge colors with darker text versions
  const getConditionStyle = (condition) => {
    // Trim whitespace and normalize the condition string
    const normalizedCondition = condition?.trim();

    const styles = {
      'New': { bg: 'bg-green-200', text: 'text-green-800', border: 'border-green-300' },
      'Brand New': { bg: 'bg-green-200', text: 'text-green-800', border: 'border-green-300' },
      'Like New': { bg: 'bg-blue-200', text: 'text-blue-800', border: 'border-blue-300' },
      'Good': { bg: 'bg-yellow-200', text: 'text-yellow-800', border: 'border-yellow-300' },
      'Fair': { bg: 'bg-orange-200', text: 'text-orange-800', border: 'border-orange-300' },
      'For Parts': { bg: 'bg-gray-300', text: 'text-gray-800', border: 'border-gray-400' },
    };

    return styles[normalizedCondition] || { bg: 'bg-blue-200', text: 'text-blue-800', border: 'border-blue-300' };
  };

  const conditionStyle = getConditionStyle(product.condition);

  const nextImage = (e) => {
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e) => {
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  return (
    <div className="bg-white rounded-3xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300">
      {/* Image Section */}
      <div className="relative bg-gray-100 overflow-hidden group rounded-t-2xl" style={{ paddingBottom: '100%' }}>
        <img
          src={images[currentImageIndex] || 'https://via.placeholder.com/400x400?text=No+Image'}
          alt={product.name}
          className="absolute inset-0 w-full h-full object-cover"
        />

        {/* Heart Button */}
        <button
          onClick={() => onToggleSave(product.id)}
          className="absolute top-3 right-3 bg-white bg-opacity-90 hover:bg-opacity-100 rounded-full p-2 shadow-md hover:scale-110 transition-all duration-200"
        >
          <Heart
            size={20}
            className={isSaved ? 'fill-red-500 text-red-500' : 'text-gray-600'}
          />
        </button>

        {/* Image Navigation Arrows */}
        {hasMultipleImages && (
          <>
            <button
              onClick={prevImage}
              className="absolute left-2 top-1/2 -translate-y-1/2 bg-white bg-opacity-90 hover:bg-opacity-100 rounded-full p-2 shadow-lg opacity-0 group-hover:opacity-100 transition-opacity duration-200"
            >
              <ChevronLeft className="text-gray-800" size={20} />
            </button>

            <button
              onClick={nextImage}
              className="absolute right-2 top-1/2 -translate-y-1/2 bg-white bg-opacity-90 hover:bg-opacity-100 rounded-full p-2 shadow-lg opacity-0 group-hover:opacity-100 transition-opacity duration-200"
            >
              <ChevronRight className="text-gray-800" size={20} />
            </button>

            {/* Image Counter Dots */}
            <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex space-x-1.5">
              {images.map((_, index) => (
                <button
                  key={index}
                  onClick={(e) => {
                    e.stopPropagation();
                    setCurrentImageIndex(index);
                  }}
                  className={`h-1.5 rounded-full transition-all duration-200 ${
                    index === currentImageIndex
                      ? 'bg-gray-800 w-4'
                      : 'bg-gray-400 w-1.5'
                  }`}
                />
              ))}
            </div>
          </>
        )}
      </div>

      {/* Content Section */}
      <div className="p-4 flex flex-col" style={{ minHeight: '280px' }}>
        {/* Product Name */}
        <h3 className="text-base font-semibold text-gray-900 mb-2">{product.name}</h3>

        {/* Year and Condition Badges */}
        <div className="flex items-center gap-2 mb-3">
          <span className="bg-white text-gray-700 border border-gray-300 px-3 py-1 rounded-md text-xs font-normal uppercase">
            {product.year || 'N/A'}
          </span>
          <span className={`${conditionStyle.bg} ${conditionStyle.text} ${conditionStyle.border} border px-3 py-1 rounded-md text-xs font-normal uppercase`}>
            {product.condition}
          </span>
        </div>

        {/* Description - Always 3 lines */}
        <div className="mb-4 flex-1">
          <p className="text-sm text-gray-600 leading-relaxed line-clamp-3">
            {product.description}
          </p>
        </div>

        {/* Price and Buy Button - Always at bottom */}
        <div className="flex items-center justify-between mt-auto">
          <div>
            <p className="text-xs text-gray-500 uppercase mb-0.5">Price</p>
            <p className="text-lg font-bold text-gray-900">${product.price.toFixed(2)}</p>
          </div>
          <button className="bg-gray-900 text-white px-6 py-2.5 rounded-full text-sm font-semibold hover:bg-gray-800 transition-colors duration-200">
            Buy Now
          </button>
        </div>
      </div>
    </div>
  );
};

const AirtableStore = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [savedProducts, setSavedProducts] = useState([]);
  const [showSavedOnly, setShowSavedOnly] = useState(false);

  // ⚠️ IMPORTANT: Replace these with your actual Airtable credentials
  const AIRTABLE_API_KEY = 'patBxMl5uxbqMh90l.d0fa8c39cd2baed95b4d5f47cfa963e3374a2fbe8999edc690dc7a35bc6d8feb';
  const AIRTABLE_BASE_ID = 'appRMrTPEDmjy6Zka';
  const AIRTABLE_TABLE_NAME = 'Inventory';

  useEffect(() => {
    fetchProducts();
    // Load saved products from localStorage
    const saved = localStorage.getItem('savedProducts');
    if (saved) {
      setSavedProducts(JSON.parse(saved));
    }
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${AIRTABLE_TABLE_NAME}`,
        {
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
          },
        }
      );

      if (!response.ok) {
        throw new Error('Failed to fetch products');
      }

      const data = await response.json();

      const formattedProducts = data.records.map(record => {
        const imageField = record.fields.Image || record.fields.image || [];
        const images = imageField.map(img => img.url);

        return {
          id: record.id,
          name: record.fields.Name || record.fields.name || 'Unnamed Product',
          price: parseFloat(record.fields.Price || record.fields.price || 0),
          description: record.fields.Description || record.fields.description || '',
          images: images.length > 0 ? images : ['https://via.placeholder.com/400x400?text=No+Image'],
          condition: record.fields.Condition || record.fields.condition || 'Unknown',
          year: record.fields.Year || record.fields.year || '',
        };
      });

      setProducts(formattedProducts);
      setLoading(false);
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const toggleSaveProduct = (productId) => {
    setSavedProducts(prev => {
      const newSaved = prev.includes(productId)
        ? prev.filter(id => id !== productId)
        : [...prev, productId];

      localStorage.setItem('savedProducts', JSON.stringify(newSaved));
      return newSaved;
    });
  };

  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.condition.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesSaved = !showSavedOnly || savedProducts.includes(product.id);

    return matchesSearch && matchesSaved;
  });

  if (loading) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-gray-900 mx-auto"></div>
          <p className="mt-4 text-gray-700 text-lg font-medium">Loading products...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-md">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Configuration Error</h2>
          <p className="text-gray-600 mb-4">{error}</p>
          <p className="text-sm text-gray-500">Please update your Airtable credentials in the code.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans" style={{fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"}}>
      {/* Header */}
      <header className="bg-white shadow-sm sticky top-0 z-40 border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 py-6 sm:px-6 lg:px-8">
          <div className="flex justify-center mb-6">
            <img 
              src="/images/logo.png" 
              alt="UnrealPrices Logo" 
              className="h-24 w-24 object-contain"
              onError={(e) => {
                e.target.style.display = 'none';
                e.target.nextSibling.style.display = 'block';
              }}
            />
            <h1 className="text-4xl font-bold text-gray-800 text-center" style={{display: 'none'}}>
              Unreal<span className="text-blue-600">Prices</span>
            </h1>
          </div>

          {/* Search and Filter */}
          <div className="flex items-center space-x-4 max-w-3xl mx-auto">
            <div className="relative flex-1">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="Search products..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-12 pr-4 py-3 rounded-full border border-gray-300 focus:border-gray-900 focus:outline-none focus:ring-2 focus:ring-gray-900 transition-all duration-200"
              />
            </div>
            <button
              onClick={() => setShowSavedOnly(!showSavedOnly)}
              className={`flex items-center space-x-2 px-6 py-3 rounded-full font-semibold transition-all duration-200 ${
                showSavedOnly
                  ? 'bg-red-500 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Heart size={20} className={showSavedOnly ? 'fill-white' : ''} />
              <span>{showSavedOnly ? 'All Products' : 'Saved'}</span>
              {savedProducts.length > 0 && !showSavedOnly && (
                <span className="bg-red-500 text-white text-xs font-bold rounded-full h-5 w-5 flex items-center justify-center">
                  {savedProducts.length}
                </span>
              )}
            </button>
          </div>
        </div>
      </header>

      {/* Products Grid */}
      <main className="max-w-7xl mx-auto px-4 py-12 sm:px-6 lg:px-8">
        {showSavedOnly && filteredProducts.length === 0 ? (
          <div className="text-center py-20">
            <Heart size={64} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-2xl font-bold text-gray-800 mb-2">No saved products yet</h3>
            <p className="text-gray-600">Click the heart icon on products to save them here</p>
            <button
              onClick={() => setShowSavedOnly(false)}
              className="mt-6 bg-gray-900 text-white px-8 py-3 rounded-full font-semibold hover:bg-gray-800 transition-colors duration-200"
            >
              Browse Products
            </button>
          </div>
        ) : filteredProducts.length === 0 ? (
          <div className="text-center py-20">
            <p className="text-gray-500 text-xl">No products found</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredProducts.map(product => (
              <ProductCard
                key={product.id}
                product={product}
                onToggleSave={toggleSaveProduct}
                isSaved={savedProducts.includes(product.id)}
              />
            ))}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-gray-50 border-t border-gray-200 mt-20">
        <div className="max-w-7xl mx-auto px-4 py-12 sm:px-6 lg:px-8">
          <div className="text-center">
            <img 
              src="/images/logo.png" 
              alt="UnrealPrices Logo" 
              className="h-12 w-12 object-contain mx-auto mb-4"
            />
            <p className="text-gray-700 font-medium">UnrealPrices - Amazing Deals, Unbeatable Prices</p>
            <p className="text-gray-500 text-sm mt-2">© 2024 UnrealPrices. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default AirtableStore;
